function openProductForm(product=null){state.productReturnView=state.view;state.dialog={type:product?'product-edit':'product-new',product};render();}function openProductDelete(product){state.dialog={type:'delete-product',product};render();}async function confirmProductDelete(){const dialog=state.dialog;if(dialog?.type!=='delete-product'||dialog.deleting)return;const pin=document.querySelector('#delete-product-pin')?.value||'';if(await pinDigest(pin)!==state.pinHash)return alert('El PIN de encargado no es correcto.');dialog.deleting=true;document.querySelector('.delete-modal')?.classList.add('is-deleting');const button=document.querySelector('[data-action="confirm-delete-product"]');if(button){button.disabled=true;button.textContent='Eliminando…';}setTimeout(async()=>{const previousProducts=state.products,previousCart=state.cart;state.products=state.products.filter(p=>p.id!==dialog.product.id);state.cart=state.cart.filter(row=>row.id!==dialog.product.id);if(!state.cart.length)state.cartDiscountRate=0;logActivity('Producto eliminado',dialog.product.name);state.dialog=null;if(!await persist()){state.products=previousProducts;state.cart=previousCart;alert('No se pudo eliminar el producto. No se hicieron cambios.');}render();},480);}
function saveProduct(form){const d=new FormData(form),old=state.dialog.product,stock=old?old.stock:Number(d.get('stock')||0),now=new Date().toISOString();const product={id:old?.id||crypto.randomUUID(),name:String(d.get('name')).trim(),brand:String(d.get('brand')||'').trim(),detail:String(d.get('detail')||'').trim(),category:String(d.get('category')).trim(),image:String(d.get('image')),code:String(d.get('code')||'').trim(),unit:String(d.get('unit')),price:Number(d.get('price')),cost:Number(d.get('cost')),stock,minimum:Number(d.get('minimum')||0),content:String(d.get('content')||'').trim(),expiry:old?productExpiry(old):String(d.get('expiry')||''),stockBatches:old?structuredClone(old.stockBatches||[]):[],soldSinceRestock:old?Number(old.soldSinceRestock||0):0,lastRestockAt:old?.lastRestockAt||null};if(old)state.products=state.products.map(p=>p.id===old.id?product:p);else{state.products.push(product);if(stock>0){product.lastRestockAt=now;product.stockBatches.push({id:crypto.randomUUID(),quantity:stock,remaining:stock,expiry:product.expiry,unitCost:product.cost,receivedAt:now});syncBatchExpiry(product);state.purchases.push({id:crypto.randomUUID(),productId:product.id,productName:product.name,quantity:stock,unit:product.unit,unitCost:product.cost,total:stock*product.cost,supplier:String(d.get('supplier')||''),date:now,operator:state.operator,type:'initial'});state.stockMoves.push({id:crypto.randomUUID(),productId:product.id,type:'initial',quantity:stock,after:stock,date:now,operator:state.operator});}}state.view=state.productReturnView||'inventario';state.productReturnView=null;state.dialog=null;state.pendingBarcode='';logActivity(old?'Producto actualizado':'Producto creado',product.name);persist().then(render);}function openMovement(type,product){state.movementReturnView=state.view==='resurtir'?'reinversion':state.view;state.dialog={type,product};render();}
async function saveMovement(form){const data=new FormData(form),p=state.dialog.product,quantity=Number(data.get('quantity'));if(!(quantity>0))return alert('Escribe una cantidad mayor a cero.');const before=structuredClone(p),previousPurchases=state.purchases,previousMoves=state.stockMoves;if(state.dialog.type==='purchase'){const unitCost=Number(data.get('unitCost'));if(!(unitCost>=0))return alert('Revisa el costo de compra.');const expiry=String(data.get('expiry')||''),now=new Date().toISOString(),previous=p.stock,combined=previous+quantity;p.cost=combined?((previous*p.cost)+(quantity*unitCost))/combined:unitCost;p.stock=combined;p.stockBatches||=[];p.stockBatches.push({id:crypto.randomUUID(),quantity,remaining:quantity,expiry,unitCost,receivedAt:now});syncBatchExpiry(p);p.lastRestockAt=now;p.soldSinceRestock=0;state.purchases.push({id:crypto.randomUUID(),productId:p.id,productName:p.name,quantity,unit:p.unit,unitCost,total:quantity*unitCost,supplier:String(data.get('supplier')||''),expiry,date:now,operator:state.operator});state.stockMoves.push({id:crypto.randomUUID(),productId:p.id,type:'purchase',quantity,after:p.stock,date:now,operator:state.operator});}else{const previous=Number(p.stock||0),now=new Date().toISOString();p.stockBatches||=[];if(quantity<previous)consumeBatchStock(p,previous-quantity);else if(quantity>previous){const added=quantity-previous;p.stockBatches.push({id:crypto.randomUUID(),quantity:added,remaining:added,expiry:'',unitCost:Number(p.cost||0),receivedAt:now,countAdjustment:true});}p.stock=quantity;syncBatchExpiry(p);state.stockMoves.push({id:crypto.randomUUID(),productId:p.id,type:'count',before:previous,quantity,delta:quantity-previous,date:now,operator:state.operator});}const audit=logActivity(state.dialog.type==='purchase'?'Compra registrada':'Conteo de inventario',p.name+' · '+quantity+' '+p.unit);if(await persist()){state.dialog=null;if(state.movementReturnView){state.view=state.movementReturnView;state.movementReturnView=null;}render();}else{Object.assign(p,before);state.purchases=previousPurchases;state.stockMoves=previousMoves;state.audit=state.audit.filter(event=>event.id!==audit.id);render();}}async function changePin(form){const data=new FormData(form),current=String(data.get('current')),next=String(data.get('next'));if(await pinDigest(current)!==state.pinHash)return alert('La contraseña actual no coincide.');if(!/^\d{4,8}$/.test(next))return alert('El PIN nuevo debe tener de 4 a 8 números.');state.pinHash=await pinDigest(next);await putSetting('pinHash',state.pinHash);logActivity('Contraseña actualizada','PIN del dispositivo');await persist();state.dialog=null;render();alert('Contraseña actualizada en este dispositivo.');}
const cats=()=>['Todos',...(state.sales.length?['Recientes']:[]),...new Set(state.products.map(p=>p.category))];const recentProductIds=()=>{const ids=new Set();for(let i=state.sales.length-1;i>=Math.max(0,state.sales.length-50)&&ids.size<12;i--)for(const item of state.sales[i].items||[]){ids.add(item.id);if(ids.size>=12)break;}return ids;};const normalizeSearch=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();function nearSearchWord(term,word){if(word.startsWith(term))return true;if(Math.abs(term.length-word.length)>1)return false;let i=0,j=0,errors=0;while(i<term.length&&j<word.length){if(term[i]===word[j]){i++;j++;continue;}if(++errors>1)return term.length===word.length&&i+1<term.length&&term[i]===word[j+1]&&term[i+1]===word[j];if(term.length>word.length)i++;else if(word.length>term.length)j++;else{i++;j++;}}return true;}
function imageFor(p){if(p.image)return p.image;const name=`${p.name} ${p.brand||''} ${p.detail||''}`.toLowerCase();if(/coca|refresco|soda/.test(name))return 'soda';if(/agua|water/.test(name))return 'water';if(/leche/.test(name))return 'milk';if(/queso/.test(name))return 'cheese';if(/jam[oó]n|pavo/.test(name))return 'turkey-leg';if(/huevo|egg/.test(name))return 'eggs';return 'chips';}
const filtered=()=>{const query=normalizeSearch(state.query),terms=query.split(' '),recent=recentProductIds();return state.products.filter(p=>{const categoryMatch=state.category==='Todos'||(state.category==='Recientes'?recent.has(p.id):p.category===state.category);if(!categoryMatch)return false;if(!query)return true;const text=normalizeSearch(`${p.name} ${p.brand||''} ${p.detail||''} ${p.code}`),words=text.split(' '),compact=text.replace(/ /g,''),compactQuery=query.replace(/ /g,'');return text.includes(query)||compact.includes(compactQuery)||terms.every(term=>words.some(word=>nearSearchWord(term,word)));});};
const cartSubtotal=()=>state.cart.reduce((n,i)=>n+i.qty*i.price,0);const cartDiscountAmount=()=>Math.round(cartSubtotal()*state.cartDiscountRate*100)/100;const cartTotal=()=>Math.max(0,Math.round((cartSubtotal()-cartDiscountAmount())*100)/100);
const today=()=>dayKey(new Date());
const todaySales=()=>state.sales.filter(s=>dayKey(s.date)===today()&&!s.voidedAt);
