function captureCartOrigin(element){const img=element?.querySelector('.product-icon');if(!img)return null;const r=img.getBoundingClientRect();return{src:img.currentSrc||img.src,rect:{left:r.left,top:r.top,width:r.width,height:r.height}};}
function animateCartFly(origin){if(!origin?.src||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const dock=document.querySelector('.cart-dock'),target=dock&&getComputedStyle(dock).display!=='none'?dock:document.querySelector('.ticket-head');if(!target)return;const to=target.getBoundingClientRect(),from=origin.rect;if(!to.width||!to.height)return;const fly=document.createElement('img');fly.src=origin.src;fly.alt='';fly.setAttribute('aria-hidden','true');fly.className='cart-fly';const size=38;fly.style.left=(from.left+from.width/2-size/2)+'px';fly.style.top=(from.top+from.height/2-size/2)+'px';document.body.append(fly);const dx=to.left+to.width/2-(from.left+from.width/2),dy=to.top+to.height/2-(from.top+from.height/2);const motion=fly.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:'translate('+dx+'px,'+dy+'px) scale(.18)',opacity:.18}],{duration:560,easing:'cubic-bezier(.2,.75,.25,1)'});motion.onfinish=()=>fly.remove();}
async function holdSale(){if(!state.cart.length)return;if(state.holds.length>=10)return alert('Ya hay 10 ventas en espera. Retoma una antes de guardar otra.');const held={id:crypto.randomUUID(),cart:structuredClone(state.cart),discountRate:state.cartDiscountRate,createdAt:new Date().toISOString(),operator:state.operator,total:cartTotal()};state.holds.push(held);state.cart=[];state.cartDiscountRate=0;logActivity('Venta puesta en espera',money(held.total));if(await persist())render();else{state.holds=state.holds.filter(row=>row.id!==held.id);state.cart=held.cart;render();}}async function resumeHeldSale(id){const held=state.holds.find(row=>row.id===id);if(!held)return;const previousHolds=state.holds,previousCart=state.cart;if(state.cart.length){if(state.holds.length>=10)return alert('Hay demasiadas ventas en espera. Guarda o retoma una primero.');state.holds=[...state.holds,{id:crypto.randomUUID(),cart:structuredClone(state.cart),discountRate:state.cartDiscountRate,createdAt:new Date().toISOString(),operator:state.operator,total:cartTotal()}];}else state.holds=state.holds.slice();state.holds=state.holds.filter(row=>row.id!==id);state.cart=structuredClone(held.cart);state.cartDiscountRate=Number(held.discountRate||0);logActivity('Venta retomada',money(held.total));if(await persist())render();else{state.holds=previousHolds;state.cart=previousCart;render();}}
function add(product,qty=1,source='tap'){const row=state.cart.find(x=>x.id===product.id),unit=product.unit==='docena'?'pieza':['kg','gramo'].includes(product.unit)?'kg':product.unit,price=product.unit==='gramo'?product.price*1000:product.unit==='docena'?product.price/12:product.price,cost=product.unit==='gramo'?product.cost*1000:product.unit==='docena'?product.cost/12:product.cost;if(row)row.qty=Math.round((row.qty+qty)*1000)/1000;else state.cart.push({id:product.id,name:product.name,unit,qty,price,cost});if(source==='scanner'){const token=++state.scanToastToken;state.scanToast='✓ '+product.name+' agregado';navigator.vibrate?.(22);setTimeout(()=>{if(state.scanToastToken===token){state.scanToast='';render();}},1300);}render();}
function portionModal(){const p=state.portionProduct,amount=Number(state.portionAmount||0),valid=Number.isInteger(amount)&&amount>0;return `<div class="modal-backdrop" data-action="dismiss-egg"><section class="weight-modal portion-modal" role="dialog" aria-modal="true" aria-labelledby="egg-title"><button class="modal-close" data-action="cancel-egg" aria-label="Cerrar">×</button><div class="weight-icon">🥚</div><span class="eyebrow">VENTA DE HUEVO</span><h2 id="egg-title">${escapeHtml(p.name)}</h2><p class="weight-hint">Precio por docena: <b>${money(p.price)}</b><span> · ${money(p.price/12)} por pieza</span></p><div class="portion-shortcuts"><button type="button" data-egg-quick="12"><b>Docena</b><small>12 piezas</small></button><button type="button" data-egg-quick="6"><b>Media docena</b><small>6 piezas</small></button><button type="button" data-egg-quick="3"><b>3 piezas</b><small>Cuarto de docena</small></button><button type="button" data-egg-quick="4"><b>4 piezas</b><small>Un tercio de docena</small></button></div><label for="egg-amount">O escribe otra cantidad de piezas</label><div class="weight-input-wrap"><input id="egg-amount" type="number" min="1" step="1" inputmode="numeric" placeholder="Ej. 3" value="${escapeHtml(state.portionAmount||'')}"><span>piezas</span></div><div class="weight-preview" id="egg-preview">${valid?`Total: ${money(p.price*amount/12)}`:'Elige una cantidad para calcular el total'}</div><button class="charge-btn" data-action="confirm-egg" ${valid?'':'disabled'}>Agregar a la cuenta <span>→</span></button></section></div>`;}
function weightModal(){const p=state.weightProduct,unit=state.weightUnit||'g',amount=Number(state.weightAmount||0),kg=unit==='g'?amount/1000:amount,valid=amount>0;return `<div class="modal-backdrop" data-action="dismiss-weight"><section class="weight-modal" role="dialog" aria-modal="true" aria-labelledby="weight-title"><button class="modal-close" data-action="cancel-weight" aria-label="Cerrar">×</button><div class="weight-icon">⚖️</div><span class="eyebrow">VENTA POR PESO</span><h2 id="weight-title">${escapeHtml(p.name)}</h2><p class="weight-hint">Precio por kilo: <b>${money(p.unit==='gramo'?p.price*1000:p.price)}</b></p><label>¿Qué cantidad pidió?</label><div class="weight-units"><button type="button" data-weight-unit="g" class="${unit==='g'?'selected':''}">Gramos</button><button type="button" data-weight-unit="kg" class="${unit==='kg'?'selected':''}">Kilos</button></div><div class="weight-input-wrap"><input id="weight-amount" type="number" min="${unit==='g'?'1':'0.001'}" step="${unit==='g'?'1':'0.001'}" inputmode="decimal" placeholder="${unit==='g'?'250':'0.25'}" value="${escapeHtml(state.weightAmount||'')}"><span>${unit==='g'?'gramos':'kilos'}</span></div><div class="weight-preview" id="weight-preview">${valid?`Total: ${money((p.unit==='gramo'?p.price*1000:p.price)*kg)}`:'Escribe la cantidad para calcular el total'}</div><button class="charge-btn" data-action="confirm-weight" ${valid?'':'disabled'}>Agregar a la cuenta <span>→</span></button></section></div>`;}function checkout(){if(!state.cart.length)return;if(!isOpen())return alert('Abre la caja antes de registrar ventas.');state.dialog={type:'payment',total:cartTotal(),subtotal:cartSubtotal(),discountAmount:cartDiscountAmount(),discountRate:state.cartDiscountRate,method:'efectivo',paid:''};render();}
async function completePayment(form){const total=cartTotal(),method=state.dialog.method,paid=method==='efectivo'?Number(new FormData(form).get('paid')):total;if(method==='efectivo'&&(!Number.isFinite(paid)||paid<total))return alert('El monto recibido debe cubrir el total.');const sale={id:crypto.randomUUID(),date:new Date().toISOString(),total,paid,change:method==='efectivo'?Math.round((paid-total)*100)/100:0,method,operator:state.operator,sessionId:state.cash.find(c=>c.status==='open')?.id||null,subtotal:cartSubtotal(),discountRate:state.cartDiscountRate,discountAmount:cartDiscountAmount(),items:structuredClone(state.cart)},previousCart=state.cart,previousDiscount=state.cartDiscountRate,previousProducts=new Map();for(const item of sale.items){const p=state.products.find(p=>p.id===item.id);if(p){if(!previousProducts.has(p.id))previousProducts.set(p.id,{stock:p.stock,soldSinceRestock:p.soldSinceRestock,stockBatches:structuredClone(p.stockBatches||[]),expiry:p.expiry});const stockQty=p.unit==='gramo'?item.qty*1000:p.unit==='docena'?item.qty/12:item.qty;item.batchAllocations=consumeBatchStock(p,stockQty);p.stock=Math.max(0,Math.round((p.stock-stockQty)*1000)/1000);p.soldSinceRestock=Number(p.soldSinceRestock||0)+stockQty;}}state.sales.push(sale);const saleAudit=logActivity('Venta registrada',money(sale.total)+' · '+sale.items.length+' productos');state.cart=[];state.cartDiscountRate=0;if(!await persist()){state.sales=state.sales.filter(row=>row.id!==sale.id);for(const [id,snapshot] of previousProducts){const p=state.products.find(row=>row.id===id);if(p)Object.assign(p,snapshot);}state.cart=previousCart;state.cartDiscountRate=previousDiscount;state.audit=state.audit.filter(event=>event.id!==saleAudit.id);return;}state.dialog=null;render();}async function addProduct(){const name=prompt('Nombre del producto');if(!name)return;const price=Number(prompt('Precio de venta ($)'));if(!(price>0))return;const cost=Number(prompt('Costo de compra ($)'));if(!(cost>=0))return;const unit=prompt('Unidad: pieza, kg o docena','pieza')||'pieza';const code=prompt('Código de barras (opcional)','')||'';state.products.push({id:crypto.randomUUID(),name,code,category:prompt('Categoría','Abarrotes')||'Abarrotes',price,cost,stock:0,unit});await persist();render();}
async function openCash(){if(isOpen())return alert('La caja ya está abierta.');const opening=state.pendingOpening??Number(prompt('Efectivo inicial en caja ($)',''));state.pendingOpening=null;if(!Number.isFinite(opening)||opening<0)return;state.cash.push({id:crypto.randomUUID(),openedAt:new Date().toISOString(),opening,status:'open',operator:state.operator,logins:[{name:state.operator,date:new Date().toISOString()}]});logActivity('Caja abierta',money(opening));await putSetting('sessionLocked',false);if(await persist())render();}
async function closeCash(){const session=state.cash.find(c=>c.status==='open');if(!session)return;if(state.cart.length)return alert('Hay una cuenta sin cobrar. Ponla en espera o vacíala antes de cerrar caja.');const sales=state.sales.filter(s=>s.date>=session.openedAt&&!s.voidedAt);const cashSales=sales.filter(s=>s.method==='efectivo').reduce((n,s)=>n+s.total,0);const nonCash=sales.filter(s=>s.method!=='efectivo').reduce((n,s)=>n+s.total,0);const cashIn=state.cash.filter(c=>c.type==='in'&&c.date>=session.openedAt).reduce((n,c)=>n+c.amount,0);const cashOutRows=state.cash.filter(c=>c.type==='out'&&c.date>=session.openedAt),cashOut=cashOutRows.reduce((n,c)=>n+c.amount,0);const expected=session.opening+cashSales+cashIn-cashOut;const productMap=new Map();for(const sale of sales){const subtotal=Number(sale.subtotal||sale.items.reduce((n,item)=>n+item.qty*item.price,0)),factor=subtotal?Number(sale.total)/subtotal:1;for(const item of sale.items){const row=productMap.get(item.id)||{name:item.name,unit:item.unit||'pieza',quantity:0,total:0};row.quantity+=item.qty;row.total+=item.qty*item.price*factor;productMap.set(item.id,row);}}state.dialog={type:'close-summary',session,sales,cashSales,nonCash,cashIn,cashOut,cashOutRows,expected,productRows:[...productMap.values()]};render();}
async function completeCashClose(form){const report=state.dialog;const counted=Number(new FormData(form).get('counted'));if(!Number.isFinite(counted)||counted<0)return alert('Escribe cuánto efectivo contaste.');const s=report.session;s.status='closed';s.closedAt=new Date().toISOString();s.expected=report.expected;s.counted=counted;s.difference=counted-report.expected;s.salesTotal=report.cashSales+report.nonCash;s.report={sales:report.sales.map(x=>({id:x.id,date:x.date,total:x.total,method:x.method,items:x.items})),products:report.productRows,cashSales:report.cashSales,nonCash:report.nonCash,cashIn:report.cashIn,cashOut:report.cashOut,cashOutRows:(report.cashOutRows||[]).map(x=>({amount:x.amount,reason:x.reason,note:x.note,date:x.date}))};logActivity('Caja cerrada',money(report.expected)+' esperado · '+money(counted)+' contado');if(await persist()){state.dialog=null;state.operator=null;state.cart=[];render();}else{s.status='open';delete s.closedAt;delete s.expected;delete s.counted;delete s.difference;delete s.salesTotal;delete s.report;state.dialog=report;state.operator=s.operator||null;render();}}async function cashMovement(type){if(type!=='out')return;state.dialog={type:'cash-out'};render();}
async function completeCashOut(form){const data=new FormData(form),amount=Number(data.get('amount'));if(!(amount>0))return alert('Escribe un monto mayor a cero.');state.cash.push({id:crypto.randomUUID(),type:'out',amount,reason:String(data.get('reason')||'otro'),note:String(data.get('note')||'').trim(),date:new Date().toISOString(),operator:state.operator,sessionId:state.cash.find(c=>c.status==='open')?.id||null});logActivity('Salida de caja',money(amount)+' · '+String(data.get('note')||data.get('reason')||'otro'));if(await persist()){state.dialog=null;render();}}
function backup(){const blob=new Blob([JSON.stringify(exportData(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`respaldo-tiendita-${today()}.json`;a.click();URL.revokeObjectURL(url);}
function restore(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const data=JSON.parse(await input.files[0].text());if(!Array.isArray(data.products)||!Array.isArray(data.sales))throw Error('Formato no válido');if(!confirm('Restaurar reemplazará los datos actuales. ¿Continuar?'))return;applyData(data);if(await persist())render();}catch(e){alert(`No se pudo restaurar el archivo: ${e.message}`);}};input.click();}
function openArchiveDialog(){const cutoff=new Date();cutoff.setFullYear(cutoff.getFullYear()-1);const count=state.sales.filter(s=>new Date(s.date)<cutoff).length;if(!count)return alert('No hay ventas con más de un año para archivar.');state.dialog={type:'archive',cutoff:cutoff.toISOString(),count};render();}function archiveDialog(){const cutoff=new Date(state.dialog.cutoff);return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">CONSERVAR ESPACIO</span><h2>Archivar ventas antiguas</h2><p>Se resumirán ${state.dialog.count} ventas anteriores al ${cutoff.toLocaleDateString('es-MX')}. Se conservarán ingresos, costo, ganancia y cantidad por mes; sus tickets detallados se quitarán después de descargar un respaldo.</p><label>PIN de encargado<input name="pin" type="password" inputmode="numeric" placeholder="Escribe tu PIN" required></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn" type="submit">Respaldar y archivar</button></div></form></div>`;}async function archiveOldSales(form){const pin=String(new FormData(form).get('pin')||'');if(await pinDigest(pin)!==state.pinHash)return alert('El PIN de encargado no es correcto.');const cutoff=new Date();cutoff.setFullYear(cutoff.getFullYear()-1);const old=state.sales.filter(s=>new Date(s.date)<cutoff);if(!old.length){state.dialog=null;render();return alert('No hay ventas con más de un año para archivar.');}const grouped=new Map();for(const sale of old){const month=dayKey(sale.date).slice(0,7);const row=grouped.get(month)||{month,sales:0,revenue:0,cost:0,profit:0,count:0};if(!sale.voidedAt){row.sales+=sale.total;row.revenue+=sale.total;row.count++;}if(!sale.voidedAt||!sale.returnedToStock)for(const i of sale.items||[])row.cost+=i.cost*i.qty;row.profit=row.revenue-row.cost;grouped.set(month,row);}const previousSales=state.sales,previousArchives=state.archives,previousCash=state.cash,audit=logActivity('Historial archivado',old.length+' ventas · '+grouped.size+' meses');backup();state.archives=[...state.archives,...grouped.values()];state.sales=state.sales.filter(s=>new Date(s.date)>=cutoff);state.cash=state.cash.map(session=>{if(session.report?.sales){const removed=session.report.sales.filter(s=>new Date(s.date)<cutoff).length;return removed?{...session,report:{...session.report,sales:session.report.sales.filter(s=>new Date(s.date)>=cutoff),archivedSalesCount:Number(session.report.archivedSalesCount||0)+removed}}:session;}return session;});state.dialog=null;if(await persist()){render();alert('Historial archivado; se conservaron los totales mensuales y se descargó un respaldo.');}else{state.sales=previousSales;state.archives=previousArchives;state.cash=previousCash;state.audit=state.audit.filter(event=>event.id!==audit.id);state.dialog={type:'archive',cutoff:cutoff.toISOString(),count:old.length};render();}}function stopCamera(){state.stream?.getTracks().forEach(t=>t.stop());state.stream=null;state.camera=null;}
async function startCamera(){if(!('BarcodeDetector'in window))return alert('Este navegador no incluye lector de códigos. Prueba con Chrome actualizado en Android o usa la pistola escáner.');try{const formats=await BarcodeDetector.getSupportedFormats();const detector=new BarcodeDetector({formats});state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false});state.view='venta';state.camera={detector,formats};render();const video=document.querySelector('#camera-video');video.srcObject=state.stream;await video.play();const scan=async()=>{if(!state.camera)return;try{const codes=await detector.detect(video);if(codes.length){const code=codes[0].rawValue;stopCamera();state.query=code;const p=state.products.find(p=>p.code===code);render();if(p)add(p,1,'scanner');else{state.pendingBarcode=code;state.dialog={type:'unknown-barcode',code};render();}return;}}catch{}requestAnimationFrame(scan);};requestAnimationFrame(scan);}catch(e){stopCamera();alert(`No se pudo abrir la cámara. Revisa el permiso del navegador. ${e.message}`);}}
function cartDock(){return `<button class="cart-dock ${state.cart.length?'shown':''}" data-action="view-cart" ${state.cart.length?'':'disabled'} aria-label="Ver cuenta, ${money(cartTotal())}"><span class="cart-dock-icon">🧺<i>${state.cart.length}</i></span><span class="cart-dock-copy"><b>Cuenta</b><small>${state.cart.length} ${state.cart.length===1?'artículo':'artículos'}</small></span><strong>${money(cartTotal())} <span>Ver →</span></strong></button>`;}
function layout(){const title={venta:'Punto de venta',inventario:'Inventario',resumen:'Resumen',reinversion:'Reinversión',resurtir:'Resurtir producto',ajustes:'Ajustes'}[state.view];return `<div class="shell"><aside class="rail"><div class="brand"><span class="brand-mark">L</span><span>la tiendita<small>punto de venta</small></span></div><nav>${nav('venta','▦','Vender')}${nav('inventario','▤','Inventario')}${nav('resumen','◷','Resumen')}${nav('reinversion','↗','Reinversión')}${nav('ajustes','⚙','Ajustes')}</nav><div class="rail-foot"><span class="status-dot ${state.folderAccess==='granted'?'online':''}"></span>${state.folderAccess==='granted'?'Carpeta conectada':state.folder?'Carpeta guardada · reconectar':'Guardado local · sin carpeta'}</div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">TU NEGOCIO, EN ORDEN</div><h1>${title}</h1></div>${state.view==='venta'?`<button class="cash-pill ${isOpen()?'open':''}" data-action="cash" aria-label="${isOpen()?'Hacer corte y cerrar la caja':'Abrir caja'}">${isOpen()?`<span class="cash-pill-dot"></span><span>Caja abierta</span><small>Corte →</small>`:'＋ Abrir caja'}</button>`:''}</header>${state.scanToast?`<div class="scan-toast" role="status">${escapeHtml(state.scanToast)}</div>`:''}${state.camera?`<section class="camera-card"><div class="section-head"><h2>Escanea el código</h2><button class="text-button" data-action="stop-camera">Cerrar cámara</button></div><video id="camera-video" playsinline></video><p>Centra el código de barras. Mantén la etiqueta enfocada y evita reflejos.</p><small>Formatos disponibles: ${state.camera.formats.join(', ')}</small></section>`:state.view==='venta'?salesPage():state.view==='inventario'?inventoryPage():state.view==='resumen'?summaryPage():state.view==='reinversion'?reinvestmentPage():state.view==='resurtir'?restockSelectionPage():settingsPage()}</main>${state.view==='venta'?cartDock():''}<nav class="mobile-nav">${nav('venta','▦','Vender')}${nav('inventario','▤','Stock')}${nav('resumen','◷','Resumen')}${nav('reinversion','↗','Reinversión')}${nav('ajustes','⚙','Ajustes')}</nav>${state.weightProduct?weightModal():''}${state.portionProduct?portionModal():''}${state.dialog?dialogView():''}</div>`;}function nav(id,icon,label){return `<button class="nav-item ${(state.view===id||(id==='reinversion'&&state.view==='resurtir'))?'active':''}" data-view="${id}"><span>${icon}</span><b>${label}</b></button>`;}
function cartStockWarning(row){const p=state.products.find(product=>product.id===row.id);if(!p)return '';const required=p.unit==='gramo'?row.qty*1000:p.unit==='docena'?row.qty/12:row.qty;if(required<=Number(p.stock||0)+0.0001)return '';return `<small class="ticket-stock-warning">Hay ${Number(p.stock||0)} ${escapeHtml(p.unit)} registrados; esta cuenta necesita ${Math.round(required*1000)/1000}.</small>`;}function salesPage(){return `<div class="page-grid"><section class="catalog"><div class="search-wrap"><span>⌕</span><input id="search" value="${escapeHtml(state.query)}" placeholder="Busca o escanea un producto" inputmode="${state.scannerMode?'none':'search'}" autocomplete="off"><button class="scanner-toggle ${state.scannerMode?'active':''}" data-action="scanner-mode" aria-pressed="${state.scannerMode}">${state.scannerMode?'✓ Pistola lista':'▦ Pistola'}</button><button class="camera-btn" data-action="camera">▣ Cámara</button></div><div class="chips">${cats().map(c=>`<button class="chip ${state.category===c?'selected':''}" data-cat="${escapeHtml(c)}">${escapeHtml(c)}</button>`).join('')}</div><div class="product-grid">${filtered().map(p=>`<button class="product-card" data-add="${p.id}"><img class="product-icon" src="./assets/products/${imageFor(p)}.svg" alt=""><span class="product-cart-indicator" data-cart-indicator="${p.id}" hidden></span><div class="product-name">${escapeHtml(p.name)}</div><div class="product-meta">${escapeHtml(p.detail||`${p.stock} ${p.unit} disponibles`)}</div><strong>${money(p.unit==='gramo'?p.price*1000:p.price)}<small>${['kg','gramo'].includes(p.unit)?' / kg':p.unit==='docena'?' / docena':''}</small></strong></button>`).join('')}</div></section><aside class="ticket"><div class="ticket-head"><div><span class="eyebrow">VENTA ACTUAL</span><h2>Cuenta</h2></div><div class="ticket-actions"><button class="text-button" data-action="cart-discount" ${state.cart.length?'':'disabled'}>${state.cartDiscountRate?'Descuento '+Math.round(state.cartDiscountRate*100)+'%':'Descuento'}</button><button class="text-button" data-action="hold-sale" ${state.cart.length?'':'disabled'}>Poner en espera</button><button class="text-button" data-action="clear">Vaciar</button></div></div>${state.holds.length?`<div class="held-sale-list"><b>En espera · ${state.holds.length}</b>${state.holds.map((held,index)=>`<button data-resume-hold="${held.id}"><span><strong>Venta ${index+1}</strong><small>${held.cart.length} productos · ${new Date(held.createdAt).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})}</small></span><b>${money(held.total)} <i>Retomar →</i></b></button>`).join('')}</div>`:''}${state.cart.length?`<div class="ticket-items">${state.cart.map(row=>`<div class="ticket-row"><div><b>${escapeHtml(row.name)}</b><small>${money(row.price)}${row.unit==='kg'?' / kg':row.unit==='pieza'?' / pieza':''}</small>${cartStockWarning(row)}</div><div class="qty"><button data-qty="${row.id}" data-delta="-1">−</button><input data-inputqty="${row.id}" value="${row.qty}"><button data-qty="${row.id}" data-delta="1">+</button><span class="qty-unit">${escapeHtml(row.unit)}</span></div><strong>${money(row.qty*row.price)}</strong></div>`).join('')}</div>`:`<div class="empty-ticket"><span>🧺</span><b>Tu cuenta está vacía</b><small>Toca un producto o escanéalo para comenzar.</small></div>`}<div class="ticket-bottom">${state.cartDiscountRate?`<div class="subtotal-line"><span>Subtotal</span><b>${money(cartSubtotal())}</b></div><div class="discount-line"><span>Descuento · ${Math.round(state.cartDiscountRate*100)}%</span><b>− ${money(cartDiscountAmount())}</b></div>`:''}<div class="total-line"><span>Total</span><strong>${money(cartTotal())}</strong></div><button class="charge-btn" data-action="charge" ${state.cart.length?'':'disabled'}>Cobrar <span>→</span></button><div class="secure-note">${state.folderAccess==='granted' ? '▣ Guardado en este teléfono y sincronizado con la carpeta' : state.folder ? '▣ Guardado en este teléfono · falta sincronizar la carpeta; reconecta desde Ajustes' : '▣ Guardado en este teléfono · puedes conectar una carpeta para otra copia'}</div></div></aside></div>`;}function daysUntilExpiry(date){if(!date)return null;const target=new Date(date+'T00:00:00'),today=new Date();today.setHours(0,0,0,0);return Math.floor((target-today)/86400000);}function expiryLabel(date){const days=daysUntilExpiry(date);if(days<0)return 'Caducó hace '+Math.abs(days)+' días';if(days===0)return 'Caduca hoy';if(days===1)return 'Caduca mañana';if(days<=7)return 'En '+days+' días';return new Date(date+'T00:00:00').toLocaleDateString('es-MX',{day:'numeric',month:'short'});}const inventoryCounts=()=>({all:state.products.length,low:state.products.filter(p=>Number(p.stock)<Number(p.minimum||0)).length,expiry:state.products.filter(p=>productExpiry(p)&&daysUntilExpiry(productExpiry(p))<=7).length});const inventoryProducts=()=>state.products.filter(p=>state.inventoryFilter==='all'||(state.inventoryFilter==='low'?Number(p.stock)<Number(p.minimum||0):productExpiry(p)&&daysUntilExpiry(productExpiry(p))<=7));
function inventoryPage(){return `<section class="inventory-panel"><div class="section-head"><div><span class="eyebrow">FICHAS Y EXISTENCIAS</span><h2>Inventario</h2></div><div class="inventory-tools"><button class="secondary-btn" data-action="export-catalog">Descargar catálogo</button><button class="secondary-btn" data-action="import-catalog">Importar catálogo</button><button class="primary-btn" data-action="new-product">＋ Nuevo producto</button></div></div><div class="inventory-filters"><button class="${state.inventoryFilter==='all'?'selected':''}" data-inventory-filter="all">Todos <b>${inventoryCounts().all}</b></button><button class="${state.inventoryFilter==='low'?'selected':''}" data-inventory-filter="low">Por reponer <b>${inventoryCounts().low}</b></button><button class="${state.inventoryFilter==='expiry'?'selected':''}" data-inventory-filter="expiry">Caducidad próxima <b>${inventoryCounts().expiry}</b></button></div><div class="inventory-cards">${inventoryProducts().map(p=>`<article class="inventory-card"><img class="inventory-art" src="./assets/products/${imageFor(p)}.svg" alt="Ilustración de ${escapeHtml(p.name)}"><div class="inventory-info"><div class="inventory-title"><div><span class="eyebrow">${escapeHtml(p.category)}</span><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml([p.brand,p.detail,p.content].filter(Boolean).join(' · '))}</p></div><div class="inventory-title-actions"><button class="icon-edit" data-edit="${p.id}" aria-label="Editar ${escapeHtml(p.name)}" title="Editar producto">✎</button><button class="icon-delete" data-delete-product="${p.id}" aria-label="Eliminar ${escapeHtml(p.name)}" title="Eliminar producto"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/></svg></button></div></div><div class="product-specs"><span>Venta: <b>${money(p.price)} / ${escapeHtml(p.unit)}</b></span><span>Costo: <b>${money(p.cost)} / ${escapeHtml(p.unit)}</b></span>${p.code?`<span>Código: <b>${escapeHtml(p.code)}</b></span>`:''}${productExpiry(p)?`<span class="${daysUntilExpiry(productExpiry(p))<=7?'expiry-warning':''}">Caduca primero: <b>${expiryLabel(productExpiry(p))}</b><small> · ${(p.stockBatches||[]).filter(b=>b.remaining>0).length} lotes con existencia</small></span>`:''}${expiryLotSummary(p)}</div><div class="stock-line"><div><small>Existencia actual</small><b class="${p.stock<Number(p.minimum||0)?'stock-alert':''}">${p.stock} ${escapeHtml(p.unit)}${p.stock<Number(p.minimum||0)?' · Reponer pronto':''}</b></div><div class="stock-actions"><button class="secondary-btn" data-purchase="${p.id}">＋ Registrar compra</button><button class="secondary-btn" data-count="${p.id}">Contar</button></div></div></div></article>`).join('')}</div></section>`;}
function csvCell(value){return '"'+String(value??'').replaceAll('"','""')+'"';}function exportCatalog(){const fields=['name','category','brand','detail','code','unit','content','cost','price','minimum','expiry','image'],labels=['nombre','categoria','marca','detalle','codigo','unidad','contenido','costo','precio','minimo','caducidad','imagen'],lines=[labels,...state.products.map(p=>fields.map(k=>p[k]??''))].map(row=>row.map(csvCell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+lines],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='catalogo-tiendita.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(ch==='"')quoted=false;else cell+=ch;}else if(ch==='"')quoted=true;else if(ch===','){row.push(cell);cell='';}else if(ch==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell='';}else cell+=ch;}if(cell.length||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}return rows.filter(r=>r.some(v=>String(v).trim()));}async function importCatalog(file){const rows=parseCsv((await file.text()).replace(/^\ufeff/,''));if(rows.length<2)return alert('El archivo no contiene productos.');const aliases={nombre:'name',categoria:'category',marca:'brand',detalle:'detail',codigo:'code',unidad:'unit',contenido:'content',costo:'cost',precio:'price',minimo:'minimum',caducidad:'expiry',imagen:'image'},columns=rows.shift().map(v=>aliases[v.trim().toLowerCase()]||v.trim().toLowerCase()),valid=rows.map(row=>Object.fromEntries(columns.map((key,i)=>[key,(row[i]||'').trim()]))).filter(r=>r.name&&Number(r.price)>0),invalid=rows.length-valid.length;if(!columns.includes('name')||!columns.includes('price'))return alert('El CSV debe incluir las columnas nombre y precio. Descarga primero el catálogo desde Inventario.');if(!valid.length)return alert('No hay filas válidas. Revisa nombre y precio.');const seen=new Set(),unique=valid.filter(r=>{const key=r.code?'c:'+r.code.toLowerCase():'n:'+r.name.toLowerCase()+'|'+String(r.category||'').toLowerCase();if(seen.has(key))return false;seen.add(key);return true;}),matches=r=>state.products.find(p=>r.code&&p.code===r.code||!r.code&&p.name.toLowerCase()===r.name.toLowerCase()&&String(p.category||'').toLowerCase()===String(r.category||'').toLowerCase()),existing=unique.filter(matches).length,adding=unique.length-existing;if(!confirm('Se agregarán '+adding+' productos y se actualizarán '+existing+' fichas. Las existencias actuales se conservarán; los productos nuevos iniciarán en cero. ¿Continuar?'))return;const previous=state.products;state.products=state.products.map(p=>({...p}));for(const r of unique){const match=matches(r),base=match||{id:crypto.randomUUID(),stock:0,soldSinceRestock:0,lastRestockAt:null,category:'Abarrotes',unit:'pieza',brand:'',detail:'',content:'',code:'',cost:0,minimum:0,expiry:'',image:'chips'},next={...base};for(const key of ['name','category','brand','detail','code','unit','content','expiry','image'])if(r[key]!==undefined&&r[key]!=='')next[key]=r[key];for(const key of ['cost','price','minimum'])if(r[key]!==undefined&&r[key]!==''&&Number.isFinite(Number(r[key])))next[key]=Number(r[key]);syncBatchExpiry(next);if(match)state.products=state.products.map(p=>p.id===match.id?next:p);else state.products.push(next);}const audit=logActivity('Catálogo importado',adding+' nuevos · '+existing+' actualizados · '+invalid+' filas omitidas');if(await persist()){render();alert('Catálogo actualizado. Se conservaron las existencias.');}else{state.products=previous;state.audit=state.audit.filter(event=>event.id!==audit.id);}}function chooseCatalogFile(){const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=()=>input.files[0]&&importCatalog(input.files[0]).catch(e=>alert('No se pudo leer el catálogo: '+e.message));input.click();}function monthStats(key){const all=state.sales.filter(s=>dayKey(s.date).slice(0,7)===key),detailed=all.filter(s=>!s.voidedAt),saved=state.archives.filter(a=>a.month===key),revenue=detailed.reduce((n,s)=>n+Number(s.total||0),0)+saved.reduce((n,a)=>n+Number(a.revenue??a.sales??0),0),cost=all.filter(s=>!s.voidedAt||!s.returnedToStock).reduce((n,s)=>n+(s.items||[]).reduce((m,i)=>m+Number(i.cost||0)*Number(i.qty||0),0),0)+saved.reduce((n,a)=>n+Number(a.cost||0),0);return{revenue,cost,profit:revenue-cost,count:all.length+saved.reduce((n,a)=>n+Number(a.count||0),0)};}function weekStats(){const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-(start.getDay()+6)%7);const end=new Date(start);end.setDate(end.getDate()+7);const all=state.sales.filter(s=>new Date(s.date)>=start&&new Date(s.date)<end),sales=all.filter(s=>!s.voidedAt),revenue=sales.reduce((n,s)=>n+Number(s.total||0),0),cost=all.filter(s=>!s.voidedAt||!s.returnedToStock).reduce((n,s)=>n+(s.items||[]).reduce((m,i)=>m+Number(i.cost||0)*Number(i.qty||0),0),0);return{revenue,profit:revenue-cost,count:sales.length};}function periodReports(){const week=weekStats(),now=new Date(),monthKey=dayKey(now).slice(0,7),month=monthStats(monthKey),previousKey=dayKey(new Date(now.getFullYear(),now.getMonth()-1,1)).slice(0,7),previous=monthStats(previousKey),change=previous.revenue?((month.revenue-previous.revenue)/previous.revenue)*100:null,year=now.getFullYear(),annual=Array.from({length:12},(_,i)=>monthStats(year+'-'+String(i+1).padStart(2,'0'))).reduce((a,m)=>({revenue:a.revenue+m.revenue,cost:a.cost+m.cost,profit:a.profit+m.profit,count:a.count+m.count}),{revenue:0,cost:0,profit:0,count:0});return `<section class="period-report"><div><span class="eyebrow">TENDENCIA DE VENTAS</span><h3>Esta semana y este mes</h3></div><div class="period-report-grid"><article><span>Esta semana</span><b>${money(week.revenue)}</b><small>${week.count} ventas · Ganancia bruta estimada: ${money(week.profit)}</small></article><article><span>Este mes</span><b>${money(month.revenue)}</b><small>${month.count} ventas · Ganancia bruta estimada: ${money(month.profit)}</small></article></div><p class="period-comparison">${change===null?'Sin ventas del mes anterior para comparar':(change>=0?'Subió ':'Bajó ')+Math.abs(change).toFixed(1)+'% frente al mes anterior'} · Mes pasado: ${money(previous.revenue)}</p><div class="annual-report"><div><span class="eyebrow">ACUMULADO ${year}</span><b>${money(annual.revenue)}</b><small>Ventas · ${annual.count} tickets</small></div><div><span>Costos estimados</span><b>${money(annual.cost)}</b></div><div><span>Ganancia bruta estimada</span><b>${money(annual.profit)}</b><small>Ventas menos costo de mercancía; no descuenta gastos del negocio.</small></div></div></section>`;}
function summaryPage(){const session=state.cash.find(c=>c.status==='open'),allSales=session?state.sales.filter(s=>s.date>=session.openedAt):state.sales.filter(s=>dayKey(s.date)===today()),sales=allSales.filter(s=>!s.voidedAt),recent=allSales.slice().reverse().slice(0,8),revenue=sales.reduce((n,s)=>n+s.total,0),profit=sales.reduce((n,s)=>n+Number(s.total||0)-(s.items||[]).reduce((m,i)=>m+Number(i.cost||0)*Number(i.qty||0),0),0)-allSales.filter(s=>s.voidedAt&&!s.returnedToStock).reduce((n,s)=>n+(s.items||[]).reduce((m,i)=>m+Number(i.cost||0)*Number(i.qty||0),0),0),cashSales=sales.filter(s=>s.method==='efectivo').reduce((n,s)=>n+s.total,0),nonCash=sales.filter(s=>s.method!=='efectivo').reduce((n,s)=>n+s.total,0),cashIn=state.cash.filter(c=>c.type==='in'&&(!session||c.date>=session.openedAt)).reduce((n,c)=>n+c.amount,0),cashOut=state.cash.filter(c=>c.type==='out'&&(!session||c.date>=session.openedAt)).reduce((n,c)=>n+c.amount,0),expected=session?session.opening+cashSales+cashIn-cashOut:0;return `<section class="summary"><span class="eyebrow">${session?'TURNO ACTUAL':'HOY'} · ${new Date().toLocaleDateString('es-MX',{weekday:'long',day:'numeric',month:'long'})}</span><h2>Así va tu tienda</h2><section class="cash-breakdown"><header><div><span class="eyebrow">CONTROL DE EFECTIVO</span><h3>${session?'Dinero en caja':'Caja cerrada'}</h3></div>${session?'<span class="cash-live"><i></i>Turno abierto</span>':''}</header><div class="cash-ledger-row"><div><b>Fondo inicial</b><small>Dinero con que abrió la caja</small></div><strong>${session?money(session.opening):'—'}</strong></div><div class="cash-ledger-row"><div><b>Ventas en efectivo</b><small>Dinero recibido en efectivo</small></div><strong class="cash-positive">+ ${money(cashSales)}</strong></div><div class="cash-ledger-row"><div><b>Tarjeta y transferencia</b><small>No se suman al efectivo del cajón</small></div><strong>${money(nonCash)}</strong></div>${cashIn?`<div class="cash-ledger-row"><div><b>Entradas registradas</b><small>Movimientos anteriores</small></div><strong class="cash-positive">+ ${money(cashIn)}</strong></div>`:''}<div class="cash-ledger-row"><div><b>Retiros y pagos</b><small>Salidas registradas en el turno</small></div><strong class="cash-negative">− ${money(cashOut)}</strong></div><div class="cash-ledger-total"><span>Efectivo esperado en caja</span><strong>${session?money(expected):'—'}</strong></div></section><div class="stat-grid summary-stat-grid"><article class="stat-card"><span>Ventas totales del turno</span><strong>${money(revenue)}</strong><small>${sales.length} ventas · cualquier forma de pago</small></article><article class="stat-card"><span>Ganancia bruta estimada</span><strong>${money(profit)}</strong><small>Ventas menos costo de los productos vendidos</small></article></div>${periodReports()}<div class="cash-actions">${isOpen()?'<button class="secondary-btn" data-action="cash-out">− Registrar salida de caja</button>':'<button class="primary-btn" data-action="cash">Abrir caja</button>'}</div><div class="inventory-panel recent"><div class="section-head"><div><span class="eyebrow">REGISTRO</span><h2>Ventas recientes</h2></div></div>${recent.length?recent.map(s=>`<button class="recent-row ${s.voidedAt?'sale-voided':''}" data-sale-receipt="${s.id}"><span>${new Date(s.date).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})} · ${escapeHtml(s.method)} · ${s.items.length} productos<small>${s.voidedAt?'ANULADA · '+escapeHtml(s.voidReason||''):'Ver ticket →'}</small></span><b>${s.voidedAt?'Anulada':money(s.total)}</b></button>`).join(''):'<p class="muted">Todavía no hay ventas en este turno.</p>'}</div></section>`;}
function loginPage(){return `<main class="login-screen"><section class="login-card"><div class="brand-mark login-mark">L</div><span class="eyebrow">CONTROL DE CAJA</span><h1>Bienvenido a tu tienda</h1><p>Identifícate para abrir el turno.</p><form id="login-form"><label>Nombre de quien abre<input name="name" autocomplete="name" placeholder="Ej. Ana" required></label><label>Fondo inicial de caja<input name="opening" inputmode="decimal" type="number" min="0" step="0.01" placeholder="Ej. 1200" required></label><label>Contraseña<input name="pin" inputmode="numeric" type="password" placeholder="PIN de 4 números" required></label><button class="charge-btn" type="submit">Entrar <span>→</span></button></form><small>PIN inicial de demostración: 1234</small></section></main>`;}function discountDialog(){return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">AUTORIZACIÓN DE ENCARGADO</span><h2>Aplicar descuento</h2><p>El descuento se aplicará a toda la cuenta y quedará reflejado en el ticket.</p><label>Porcentaje de descuento<input name="percent" type="number" min="0" max="100" step="1" inputmode="numeric" value="${Math.round(state.cartDiscountRate*100)}" required></label><label>Motivo (opcional)<input name="reason" placeholder="Ej. promoción"></label><label>PIN de encargado<input name="pin" type="password" inputmode="numeric" placeholder="Escribe tu PIN" required></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn" type="submit">Aplicar descuento</button></div></form></div>`;}async function applyCartDiscount(form){const data=new FormData(form),percent=Number(data.get('percent')),pin=String(data.get('pin')||'');if(!Number.isFinite(percent)||percent<0||percent>100)return alert('El descuento debe estar entre 0% y 100%.');if(await pinDigest(pin)!==state.pinHash)return alert('El PIN de encargado no es correcto.');state.cartDiscountRate=percent/100;const reason=String(data.get('reason')||'').trim();logActivity(percent?'Descuento aplicado':'Descuento retirado',percent+'%'+(reason?' · '+reason:''));state.dialog=null;render();}
function paymentDialog(){const d=state.dialog,total=d.total,paid=Number(d.paid||0),cash=d.method==='efectivo',valid=!cash||paid>=total;return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal payment-modal" id="dialog-form" role="dialog" aria-modal="true" aria-labelledby="payment-title"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">FINALIZAR VENTA</span><h2 id="payment-title">¿Cómo va a pagar?</h2><div class="payment-total"><span>Total a cobrar</span><strong>${money(total)}</strong></div>${d.discountAmount?`<div class="payment-discount"><span>Subtotal ${money(d.subtotal)} · descuento ${Math.round(d.discountRate*100)}%</span><b>− ${money(d.discountAmount)}</b></div>`:''}<div class="payment-methods"><button type="button" class="payment-option ${cash?'selected':''}" data-payment-method="efectivo"><span>💵</span><b>Efectivo</b></button><button type="button" class="payment-option ${d.method==='tarjeta'?'selected':''}" data-payment-method="tarjeta"><span>💳</span><b>Tarjeta</b></button><button type="button" class="payment-option ${d.method==='transferencia'?'selected':''}" data-payment-method="transferencia"><span>🏦</span><b>Transferencia</b></button></div>${cash?`<label class="payment-received">¿Cuánto pagó el cliente?<div class="money-input"><span>$</span><input id="payment-received" name="paid" type="number" min="${total}" step="0.01" inputmode="decimal" placeholder="Escribe el monto" value="${escapeHtml(d.paid||'')}" required></div></label><div class="payment-change"><span>Cambio</span><strong id="payment-change">${money(Math.max(0,paid-total))}</strong></div>`:`<div class="card-payment-note"><span>✓</span><p>Se registrará el cobro con ${d.method==='transferencia'?'transferencia':'tarjeta'} por <b>${money(total)}</b>.</p></div>`}<div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Volver</button><button class="primary-btn" type="submit" ${valid?'':'disabled'}>Confirmar cobro</button></div></form></div>`;}function unknownBarcodeDialog(){return `<div class="modal-backdrop" data-action="close-dialog"><section class="form-modal unknown-barcode-modal" role="dialog" aria-modal="true" aria-labelledby="unknown-barcode-title"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">CÓDIGO ESCANEADO</span><div class="unknown-barcode-icon">⌕</div><h2 id="unknown-barcode-title">No está en el inventario</h2><p>Código leído: <b>${escapeHtml(state.dialog.code)}</b>. Puedes agregarlo para la próxima venta.</p><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Volver a vender</button><button type="button" class="primary-btn" data-action="unknown-add-product">Agregar producto</button></div></section></div>`;}
function deleteProductDialog(){const p=state.dialog.product,inCart=state.cart.some(row=>row.id===p.id);return `<div class="modal-backdrop" data-action="close-dialog"><section class="form-modal delete-modal" role="dialog" aria-modal="true" aria-labelledby="delete-product-title"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">INVENTARIO</span><div class="delete-product-visual"><img class="delete-product-art" src="./assets/products/${imageFor(p)}.svg" alt=""><span class="delete-bin" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/></svg></span></div><h2 id="delete-product-title">¿Eliminar “${escapeHtml(p.name)}”?</h2><p>Ya no aparecerá en el inventario ni en futuras ventas. El historial de ventas y cortes anteriores se conservará.${inCart?' También se quitará de la cuenta actual.':''}</p><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Conservar</button><label class="delete-pin-label">PIN de encargado<input id="delete-product-pin" type="password" inputmode="numeric" autocomplete="current-password" placeholder="Escribe tu PIN" required></label><button type="button" class="danger-btn" data-action="confirm-delete-product">Eliminar producto</button></div></section></div>`;}
function cashOutDialog(){return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">CONTROL DE CAJA</span><h2>Registrar salida de caja</h2><p>Indica a dónde va el dinero para que el corte muestre el efectivo restante.</p><label>¿Para qué sale el dinero?<select name="reason" required><option value="proveedor">Pagar a un proveedor</option><option value="resguardo">Guardar o depositar</option><option value="otro">Otro retiro</option></select></label><label>Monto que salió ($)<input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="Ej. 350" required></label><label>Detalle o proveedor (opcional)<input name="note" placeholder="Ej. Pago a Bimbo"></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn" type="submit">Registrar salida</button></div></form></div>`;}
function dialogView(){const d=state.dialog;if(d.type==='delete-product')return deleteProductDialog();if(d.type==='sale-receipt')return saleReceiptDialog();if(d.type==='void-sale')return voidSaleDialog();if(d.type==='unknown-barcode')return unknownBarcodeDialog();if(d.type==='close-summary')return closeCashDialog();if(d.type==='cash-out')return cashOutDialog();if(d.type==='payment')return paymentDialog();if(d.type==='discount')return discountDialog();if(d.type==='archive')return archiveDialog();const p=d.product||{},titles={'product-new':'Nuevo producto','product-edit':'Editar producto',purchase:'Registrar compra',count:'Contar existencias',pin:'Cambiar contraseña'};if(d.type==='purchase'||d.type==='count')return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">${d.type==='purchase'?'ENTRADA DE MERCANCÍA':'CONTEO FÍSICO'}</span><h2>${titles[d.type]}</h2><p>${escapeHtml(p.name)} · ${escapeHtml(p.detail||p.unit)}</p><label>${d.type==='purchase'?'Cantidad que llegó':'Existencia encontrada'} (${escapeHtml(p.unit)})<input name="quantity" type="number" min="0.001" step="0.001" required autofocus></label>${d.type==='purchase'?`<label>Costo por ${escapeHtml(p.unit)} ($)<input name="unitCost" type="number" min="0" step="0.01" value="${p.cost||0}" required></label><label>Caducidad de este lote (opcional)<input name="expiry" type="date"></label><label>Proveedor (opcional)<input name="supplier" placeholder="Nombre del proveedor"></label>`:''}<div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn" type="submit">${d.type==='purchase'?'Guardar compra':'Guardar conteo'}</button></div></form></div>`;if(d.type==='pin')return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">SEGURIDAD</span><h2>Cambiar contraseña</h2><label>Contraseña actual<input name="current" type="password" inputmode="numeric" required></label><label>Nueva contraseña (4 a 8 números)<input name="next" type="password" inputmode="numeric" minlength="4" maxlength="8" required></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn">Guardar contraseña</button></div></form></div>`;const editing=d.type==='product-edit';return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal product-form" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">FICHA DE PRODUCTO</span><h2>${titles[d.type]}</h2><div class="form-grid"><label>Nombre<input name="name" value="${escapeHtml(p.name||'')}" placeholder="Ej. Agua natural" required></label><label>Marca<input name="brand" value="${escapeHtml(p.brand||'')}" placeholder="Ej. Bonafont"></label><label>Presentación / detalle<input name="detail" value="${escapeHtml(p.detail||'')}" placeholder="Ej. Botella · 1 L"></label><label>Categoría<input name="category" value="${escapeHtml(p.category||'Abarrotes')}" placeholder="Bebidas, botanas, cremería" required></label><label>Código de barras<input name="code" value="${escapeHtml(p.code||state.pendingBarcode||'')}" placeholder="Opcional"></label><label>Imagen<select name="image">${[['soda','Refresco'],['water','Botella de agua'],['milk','Leche'],['cheese','Queso'],['turkey-leg','Jamón de pavo'],['eggs','Huevo'],['chips','Botanas']].map(([id,label])=>`<option value="${id}" ${(p.image||'chips')===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Se vende por<select name="unit">${['pieza','paquete','kg','gramo','docena'].map(u=>`<option ${p.unit===u?'selected':''}>${u}</option>`).join('')}</select></label><label>Contenido neto<input name="content" value="${escapeHtml(p.content||'')}" placeholder="Ej. 600 ml, 200 g"></label><label>Costo de compra ($)<input name="cost" type="number" min="0" step="0.01" value="${p.cost||0}" required></label><label>Precio de venta ($)<input name="price" type="number" min="0.01" step="0.01" value="${p.price||''}" required></label>${editing?'':`<label>Existencia inicial<input name="stock" type="number" min="0" step="0.001" value="0"></label><label>Proveedor (opcional)<input name="supplier" placeholder="Nombre del proveedor"></label>`}<label>Aviso de pocas existencias<input name="minimum" type="number" min="0" step="0.001" value="${p.minimum||0}"></label>${editing?'':`<label>Caducidad inicial (opcional)<input name="expiry" type="date" value="${p.expiry||''}"></label>`}</div><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="primary-btn">${editing?'Guardar cambios':'Crear producto'}</button></div></form></div>`;}
function purchaseHistory(){if(!state.purchases.length)return `<section class="purchase-history"><span class="eyebrow">REGISTRO</span><h3>Compras recientes</h3><p>Aún no hay compras registradas.</p></section>`;return `<section class="purchase-history"><div class="section-head"><div><span class="eyebrow">REGISTRO</span><h3>Compras recientes</h3></div><span class="purchase-count">${state.purchases.length} movimientos</span></div><div class="purchase-history-list">${state.purchases.slice().reverse().slice(0,12).map(entry=>{const idx=state.purchases.findIndex(row=>row.id===entry.id),previous=state.purchases.slice(0,idx).reverse().find(row=>row.productId===entry.productId&&Number.isFinite(Number(row.unitCost)));const delta=previous?Number(entry.unitCost)-Number(previous.unitCost):0;return `<article><div><b>${escapeHtml(entry.productName||'Producto')}</b><small>${new Date(entry.date).toLocaleString('es-MX')} · ${escapeHtml(entry.supplier||'Sin proveedor')}</small>${previous&&delta!==0?`<small class="purchase-delta ${delta>0?'up':'down'}">${delta>0?'Subió ':'Bajó '}${money(Math.abs(delta))} por ${escapeHtml(entry.unit||'unidad')}</small>`:''}</div><div><b>${money(entry.total)}</b><small>${entry.quantity} ${escapeHtml(entry.unit||'unidad')} · ${money(entry.unitCost)} c/u${entry.expiry?' · Caduca '+expiryLabel(entry.expiry):''}</small></div></article>`}).join('')}</div></section>`;}
function reinvestmentPage(){return `<section class="summary reinvestment-home"><span class="eyebrow">COMPRAS Y EXISTENCIAS</span><h2>Reinversión</h2><p class="settings-intro">¿Qué necesitas hacer hoy?</p><div class="reinvestment-actions"><button class="reinvestment-choice" data-action="choose-restock"><span class="choice-icon">↻</span><span><b>Resurtir producto</b><small>Agrega mercancía a una ficha existente.</small></span><strong>→</strong></button><button class="reinvestment-choice" data-action="new-product"><span class="choice-icon">＋</span><span><b>Producto nuevo</b><small>Crea su ficha y registra la cantidad inicial.</small></span><strong>→</strong></button></div>${purchaseHistory()}</section>`;}
function restockSelectionPage(){const query=state.restockQuery.toLowerCase();const products=state.products.filter(p=>`${p.name} ${p.brand||''} ${p.detail||''} ${p.code||''}`.toLowerCase().includes(query));return `<section class="summary restock-selection"><button class="text-button back-link" data-action="back-reinvestment">← Volver a Reinversión</button><span class="eyebrow">INVENTARIO</span><h2>Resurtir producto</h2><p class="settings-intro">Busca y elige el producto que llegó. Se sumará a la existencia actual.</p><div class="search-wrap restock-search"><span>⌕</span><input id="restock-search" value="${escapeHtml(state.restockQuery)}" placeholder="Nombre, marca o código de barras" autocomplete="off"></div><div class="restock-list">${products.map(p=>`<article class="restock-card"><img src="./assets/products/${imageFor(p)}.svg" alt=""><div class="restock-info"><span class="eyebrow">${escapeHtml(p.category)}</span><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml([p.brand,p.detail,p.content].filter(Boolean).join(' · '))}</p><div class="restock-stats"><span>Existencia <b>${p.stock} ${escapeHtml(p.unit)}</b></span><span>Vendidas desde compra <b>${Number(p.soldSinceRestock||0)} ${escapeHtml(p.unit)}</b></span><span>Costo actual <b>${money(p.cost)} / ${escapeHtml(p.unit)}</b></span></div></div><div class="restock-actions"><button class="primary-btn" data-purchase="${p.id}">Elegir y resurtir</button></div></article>`).join('')||'<p class="muted">No hay productos que coincidan con la búsqueda.</p>'}</div></section>`;}
function updateCashCount(event){const form=document.querySelector('#dialog-form');if(!form)return;const fields=[...form.querySelectorAll('[data-denomination]')],totalInput=form.querySelector('[name="counted"]'),preview=document.querySelector('#cash-count-total');if(event?.target===totalInput)fields.forEach(input=>input.value='');const hasCounts=fields.some(input=>input.value!==''),sum=fields.reduce((total,input)=>total+Number(input.dataset.denomination)*Math.max(0,Number(input.value)||0),0);if(hasCounts)totalInput.value=sum.toFixed(2);if(preview)preview.textContent=money(hasCounts?sum:Number(totalInput.value||0));}function voidSaleDialog(){const sale=state.sales.find(row=>row.id===state.dialog.saleId);if(!sale)return '';return `<div class="modal-backdrop" data-action="close-dialog"><form class="form-modal void-sale-modal" id="dialog-form"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><span class="eyebrow">CONTROL DE VENTAS</span><h2>Anular venta</h2><p>Se anulará el ticket de ${new Date(sale.date).toLocaleString('es-MX')} por <b>${money(sale.total)}</b>. El ticket se conservará como anulado en el historial.</p>${sale.method==='efectivo'?'<p>Si la venta fue de otro turno, el reembolso se registrará como salida de efectivo en la caja actual.</p>':'<p>La anulación no devuelve el dinero desde la terminal. Si fue tarjeta o transferencia, procesa también la devolución en ese servicio.</p>'}<label>Motivo de anulación<textarea name="reason" rows="2" maxlength="160" placeholder="Ej. El cliente devolvió la compra" required></textarea></label><label class="void-restock"><input name="restock" type="checkbox" checked> Regresar los productos a existencias</label><label>PIN de encargado<input name="pin" type="password" inputmode="numeric" placeholder="Escribe tu PIN" required></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Cancelar</button><button class="danger-btn" type="submit">Confirmar anulación</button></div></form></div>`;}async function completeSaleVoid(form){const sale=state.sales.find(row=>row.id===state.dialog.saleId),data=new FormData(form),reason=String(data.get('reason')||'').trim(),pin=String(data.get('pin')||''),session=state.cash.find(c=>c.status==='open');if(!session)return alert('Abre una caja para registrar la anulación y cualquier reembolso en efectivo.');if(!sale||sale.voidedAt)return alert('Esta venta ya fue anulada o ya no está disponible.');if(reason.length<4)return alert('Escribe un motivo de al menos 4 caracteres.');if(await pinDigest(pin)!==state.pinHash)return alert('El PIN de encargado no es correcto.');const restock=data.get('restock')==='on',previousCash=state.cash,changes=[];sale.voidedAt=new Date().toISOString();sale.voidReason=reason;sale.voidedBy=state.operator||'Operador';sale.returnedToStock=restock;const sameSession=sale.sessionId?sale.sessionId===session.id:new Date(sale.date)>=new Date(session.openedAt);if(restock)for(const item of sale.items||[]){const product=state.products.find(p=>p.id===item.id);if(!product)continue;const quantity=product.unit==='gramo'?item.qty*1000:product.unit==='docena'?item.qty/12:item.qty;changes.push({product,stock:product.stock,sold:Number(product.soldSinceRestock||0),batches:structuredClone(product.stockBatches||[]),expiry:product.expiry});product.stock=Math.round((Number(product.stock||0)+quantity)*1000)/1000;restoreBatchStock(product,item.batchAllocations,quantity);if(!product.lastRestockAt||new Date(sale.date)>=new Date(product.lastRestockAt))product.soldSinceRestock=Math.max(0,Number(product.soldSinceRestock||0)-quantity);}if(sale.method==='efectivo'&&!sameSession){state.cash=[...state.cash,{id:crypto.randomUUID(),type:'out',amount:Number(sale.total||0),reason:'devolucion',note:'Reembolso por ticket '+sale.id.slice(0,8)+' · '+reason,date:new Date().toISOString(),operator:state.operator,sessionId:session.id}];}const audit=logActivity('Venta anulada',sale.id.slice(0,8)+' · '+money(sale.total)+' · '+(restock?'existencias repuestas':'sin reposición')+' · '+reason);if(await persist()){state.dialog=null;render();alert(sale.method==='efectivo'&&!sameSession?'Venta anulada. El reembolso quedó registrado como salida de caja.':'Venta anulada; el ticket y el movimiento quedaron registrados.');}else{delete sale.voidedAt;delete sale.voidReason;delete sale.voidedBy;delete sale.returnedToStock;state.cash=previousCash;for(const change of changes){change.product.stock=change.stock;change.product.soldSinceRestock=change.sold;change.product.stockBatches=change.batches;change.product.expiry=change.expiry;}state.audit=state.audit.filter(event=>event.id!==audit.id);render();}}function saleReceiptDialog(){const s=state.sales.find(row=>row.id===state.dialog.saleId),voided=!!s?.voidedAt;if(!s)return `<div class="modal-backdrop"><section class="form-modal"><h2>Ticket no disponible</h2><button class="secondary-btn" data-action="cancel-dialog">Cerrar</button></section></div>`;return `<div class="modal-backdrop" data-action="close-dialog"><section class="form-modal sale-receipt" role="dialog" aria-modal="true" aria-labelledby="receipt-title"><button type="button" class="modal-close" data-action="cancel-dialog" aria-label="Cerrar">×</button><div class="receipt-brand"><div class="brand-mark">L</div><span class="eyebrow">COMPROBANTE DE VENTA</span><h2 id="receipt-title">La Tiendita</h2><p>Gracias por su compra</p></div><div class="receipt-meta"><span>Fecha</span><b>${new Date(s.date).toLocaleString('es-MX')}</b><span>Atendió</span><b>${escapeHtml(s.operator||'Operador')}</b><span>Pago</span><b>${escapeHtml(s.method)}</b></div><div class="receipt-items">${s.items.map(i=>`<div><span>${escapeHtml(i.name)}<small>${i.qty} ${escapeHtml(i.unit||'pieza')} × ${money(i.price)}</small></span><b>${money(i.qty*i.price)}</b></div>`).join('')}</div><div class="receipt-total"><span>${voided?'VENTA ANULADA':'Total'}</span><b>${money(s.total)}</b></div>${voided?`<p class="void-notice">Anulada el ${new Date(s.voidedAt).toLocaleString('es-MX')} · ${escapeHtml(s.voidReason||'')}</p>`:''}${s.discountAmount?`<div class="receipt-meta receipt-payment"><span>Subtotal</span><b>${money(s.subtotal)}</b><span>Descuento</span><b>− ${money(s.discountAmount)}</b></div>`:''}${s.method==='efectivo'?`<div class="receipt-meta receipt-payment"><span>Recibido</span><b>${money(s.paid)}</b><span>Cambio</span><b>${money(s.change)}</b></div>`:''}<div class="dialog-actions receipt-actions">${!voided&&isOpen()?'<button type="button" class="danger-btn" data-action="void-sale">Anular venta</button>':''}<button type="button" class="secondary-btn" data-action="share-receipt">Compartir</button><button type="button" class="primary-btn" data-action="print-receipt">Imprimir</button></div></section></div>`;}function receiptText(s){return ['LA TIENDITA','Comprobante de venta',new Date(s.date).toLocaleString('es-MX'),'Atendió: '+(s.operator||'Operador'),'Pago: '+s.method,'------------------------------',...s.items.map(i=>i.name+' · '+i.qty+' '+(i.unit||'pieza')+' × '+money(i.price)+' = '+money(i.qty*i.price)),'------------------------------',...(s.discountAmount?['Subtotal: '+money(s.subtotal),'Descuento: -'+money(s.discountAmount)]:[]),'TOTAL: '+money(s.total),...(s.method==='efectivo'?['Recibido: '+money(s.paid),'Cambio: '+money(s.change)]:[]),'Gracias por su compra'].join('\n');}async function shareReceipt(){const s=state.sales.find(row=>row.id===state.dialog.saleId);if(!s)return;const text=receiptText(s);if(navigator.share){try{await navigator.share({title:'Ticket de La Tiendita',text});return;}catch(error){if(error.name==='AbortError')return;}}const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ticket-'+s.id.slice(0,8)+'.txt';a.click();URL.revokeObjectURL(url);}
function closeCashDialog(){const d=state.dialog;return `<div class="modal-backdrop" data-action="close-dialog"><section class="form-modal close-report"><button class="modal-close" data-action="cancel-dialog">×</button><span class="eyebrow">CIERRE DE TURNO · ${escapeHtml(d.session.operator||'')}</span><h2>Resumen de caja</h2><p class="report-period">${new Date(d.session.openedAt).toLocaleString('es-MX')} — ${new Date().toLocaleString('es-MX')}</p><div class="report-totals"><div><span>Ventas en efectivo</span><b>${money(d.cashSales)}</b></div><div><span>Tarjeta y transferencia</span><b>${money(d.nonCash)}</b></div><div><span>Entradas de caja</span><b>${money(d.cashIn)}</b></div><div><span>Salidas de caja</span><b>− ${money(d.cashOut)}</b></div><div class="report-expected"><span>Fondo inicial + efectivo neto</span><b>${money(d.expected)}</b></div></div><h3>Salidas de efectivo · ${(d.cashOutRows||[]).length} movimientos</h3><div class="report-products">${(d.cashOutRows||[]).map(x=>`<div><span>${x.reason==='proveedor'?'Pago a proveedor':x.reason==='resguardo'?'Retiro para guardar o depositar':x.reason==='devolucion'?'Reembolso de venta':'Otro retiro'}${x.note?` · ${escapeHtml(x.note)}`:''}<small>${new Date(x.date).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})}</small></span><b>− ${money(x.amount)}</b></div>`).join('')||'<p class="muted">No hubo retiros ni pagos de caja.</p>'}</div><h3>Productos vendidos · ${d.productRows.length} productos distintos</h3><div class="report-products">${d.productRows.map(p=>`<div><span>${escapeHtml(p.name)} <small>× ${p.quantity} ${escapeHtml(p.unit||'pieza')}</small></span><b>${money(p.total)}</b></div>`).join('')||'<p class="muted">No se registraron ventas en este turno.</p>'}</div><h3>Ventas del turno · ${d.sales.length} tickets</h3><div class="report-tickets">${d.sales.map(s=>`<article><header><b>${new Date(s.date).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})} · ${escapeHtml(s.method)}</b><strong>${money(s.total)}</strong></header><p>${s.items.map(i=>`${escapeHtml(i.name)} × ${i.qty} ${escapeHtml(i.unit||'pieza')}`).join(' · ')}</p></article>`).join('')||'<p class="muted">Sin tickets.</p>'}</div><form id="dialog-form"><h3 class="cash-count-heading">Cuenta el efectivo</h3><p class="cash-count-help">Escribe cuántos billetes y monedas hay. El total se calcula solo.</p><div class="cash-denominations">${[[1000,'$1,000'],[500,'$500'],[200,'$200'],[100,'$100'],[50,'$50'],[20,'$20'],[10,'$10'],[5,'$5'],[2,'$2'],[1,'$1'],[0.5,'$0.50']].map(([value,label])=>`<label>${label}<input data-denomination="${value}" type="number" min="0" step="1" inputmode="numeric" placeholder="0"></label>`).join('')}</div><div class="cash-count-preview"><span>Total contado en cajón</span><b id="cash-count-total">$0.00</b></div><label>O escribe el total manualmente ($)<input name="counted" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Escribe el total contado" required></label><div class="dialog-actions"><button type="button" class="secondary-btn" data-action="cancel-dialog">Volver</button><button class="primary-btn">Confirmar corte y cerrar caja</button></div></form></section></div>`;}function settingsPage(){return `<section class="settings-page"><span class="eyebrow">PREFERENCIAS DEL NEGOCIO</span><h2>Cuida y administra tu tienda</h2><p class="settings-intro">Datos, copias de seguridad y acceso del personal.</p><details class="quick-guide"><summary><span><b>Guía rápida</b><small>Apertura, venta, resurtido y cierre</small></span><i>⌄</i></summary><div class="quick-guide-steps"><article><b>1 · Abre la caja</b><p>Escribe quién inicia, el fondo que deja en caja y el PIN.</p></article><article><b>2 · Registra la venta</b><p>Toca un producto, usa una pistola configurada como teclado o prueba Cámara si el navegador es compatible y tiene permiso.</p></article><article><b>3 · Cobra</b><p>Elige efectivo, tarjeta o transferencia. En efectivo, registra lo recibido para calcular el cambio.</p></article><article><b>4 · Repón mercancía</b><p>En Reinversión busca el producto y registra cantidad, costo, proveedor y caducidad del lote si aplica.</p></article><article><b>5 · Haz el corte y respaldo</b><p>En Vender usa el indicador de caja para revisar ventas y cerrar el turno. En Ajustes descarga respaldos con regularidad.</p></article></div></details><article class="setting-card storage-status-card"><div class="setting-icon">▣</div><div class="setting-copy"><h3>Guardado en este teléfono</h3><p>Las ventas se guardan primero en el almacenamiento local de esta aplicación; no necesitas tener una carpeta conectada para abrir caja.</p><small>${state.storagePersisted===true?'Chrome protege estos datos contra la limpieza automática.':state.storagePersisted===false?'Chrome no confirmó protección contra limpieza automática; descarga respaldos con frecuencia.':'Estado de almacenamiento no disponible.'}${state.storageUsage!==null?' · Uso aproximado: '+formatBytes(state.storageUsage)+(state.storageQuota?' de '+formatBytes(state.storageQuota):''):''}</small></div></article><article class="setting-card"><div class="setting-icon">▱</div><div class="setting-copy"><h3>Carpeta de datos</h3><p>${state.folder?(state.folderAccess==='granted'?'La carpeta está activa y recibe los guardados. Se conserva una copia local temporal por si Chrome retira el permiso.':'La carpeta y su vínculo siguen guardados. Chrome retiró temporalmente el permiso; pulsa Reconectar carpeta para continuar sin volver a buscarla.'):'Elige dónde guardar tus datos. La información también se conserva en este dispositivo.'}</p></div><button class="primary-btn" data-action="folder">${state.folder?(state.folderAccess==='granted'?'Cambiar carpeta':'Reconectar carpeta'):'Elegir carpeta'}</button></article><article class="setting-card"><div class="setting-icon">◉</div><div class="setting-copy"><h3>Bloqueo automático</h3><p>Protege la pantalla cuando no se usa. La caja permanece abierta y el PIN permite continuar.</p></div><select class="setting-select" data-setting="auto-lock"><option value="3" ${state.autoLockMinutes===3?'selected':''}>Después de 3 minutos</option><option value="5" ${state.autoLockMinutes===5?'selected':''}>Después de 5 minutos</option><option value="10" ${state.autoLockMinutes===10?'selected':''}>Después de 10 minutos</option><option value="0" ${state.autoLockMinutes===0?'selected':''}>Desactivado</option></select></article><article class="setting-card"><div class="setting-icon">↓</div><div class="setting-copy"><h3>Respaldo de la tienda</h3><p>Descarga un archivo para guardar tus productos, ventas y cortes. Puedes cargarlo para recuperar la información.</p></div><div class="setting-buttons"><button class="secondary-btn" data-action="backup">Descargar respaldo</button><button class="secondary-btn" data-action="restore">Restaurar respaldo</button></div></article><article class="setting-card"><div class="setting-icon">◷</div><div class="setting-copy"><h3>Historial de ventas</h3><p>Detalle guardado: ${state.sales.length} ventas · Resúmenes conservados: ${state.archives.length} meses.</p><small>Antes de eliminar detalle antiguo, se guardará un respaldo y se conservarán los totales por mes.</small></div><button class="secondary-btn" data-action="archive">Archivar detalle mayor a un año</button></article><article class="setting-card activity-card"><div class="setting-icon">≋</div><div class="setting-copy"><h3>Actividad reciente</h3><p>Últimas acciones registradas en esta caja.</p><div class="activity-list">${state.audit.slice().reverse().slice(0,12).map(event=>`<div><span><b>${escapeHtml(event.action)}</b><small>${new Date(event.date).toLocaleString('es-MX')} · ${escapeHtml(event.operator)}${event.detail?' · '+escapeHtml(event.detail):''}</small></span></div>`).join('')||'<small>Aún no hay acciones registradas.</small>'}</div></div></article><article class="setting-card"><div class="setting-icon">⌑</div><div class="setting-copy"><h3>Contraseña de acceso</h3><p>PIN de demostración inicial: 1234. Cámbialo para este dispositivo.</p></div><button class="secondary-btn" data-action="change-pin">Cambiar contraseña</button></article><article class="setting-card"><div class="setting-icon">↪</div><div class="setting-copy"><h3>Turno actual</h3><p>Sesión: ${escapeHtml(state.operator||'Sin operador')}</p></div><button class="secondary-btn" data-action="logout">Cerrar sesión</button></article></section>`;}function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function lockPage(){return `<main class="login-screen"><section class="login-card"><div class="brand-mark login-mark">L</div><span class="eyebrow">SESIÓN PROTEGIDA</span><h1>Hola, ${escapeHtml(state.operator||'Operador')}</h1><p>La caja sigue abierta. Ingresa tu contraseña para continuar.</p><form id="lock-form"><label>Contraseña<input name="pin" inputmode="numeric" type="password" placeholder="Tu PIN" required autofocus></label><button class="charge-btn" type="submit">Desbloquear <span>→</span></button></form><small>El turno y la cuenta actual siguen abiertos.</small></section></main>`;}async function unlock(form){const pin=String(new FormData(form).get('pin')||'');if(await pinDigest(pin)!==state.pinHash){form.reset();return alert('La contraseña no es correcta.');}state.locked=false;await putSetting('sessionLocked',false);render();}function scheduleAutoLock(){clearTimeout(state.idleTimer);if(state.locked||!state.operator||!isOpen()||!state.autoLockMinutes)return;state.idleTimer=setTimeout(()=>{if(state.operator&&isOpen()){stopCamera();state.locked=true;putSetting('sessionLocked',true);render();}},state.autoLockMinutes*60000);}
function render(){document.querySelector('#app').innerHTML=state.locked?lockPage():state.operator?layout():loginPage();bind();scheduleAutoLock();}
